import View from 'ol/View.js';
import Map from 'ol/Map.js';
import TileLayer from 'ol/layer/Tile.js';
import OSM from 'ol/source/OSM.js';

import Feature from 'ol/Feature.js';
import Point from 'ol/geom/Point.js';
import MultiPoint from 'ol/geom/MultiPoint.js';
//import Icon from 'ol/style/Icon.js';
import VectorLayer from 'ol/layer/Vector.js';
import VectorSource from 'ol/source/Vector.js';

import { Fill, Stroke, Style, Circle as CircleStyle } from 'ol/style.js';
import { fromLonLat } from 'ol/proj.js';
import Overlay from 'ol/Overlay.js';


import { csv } from 'd3'; // Using a familar parser for csv files

const isNginx = window.location.pathname.includes('outcrops');
const isGitHubPages = window.location.pathname.includes('theimipolexg.github.io');

let csvFile = '/roadsidesites.csv';
if (isNginx) {
  csvFile = '/outcrops/roadsidesites.csv';
} else if (isGitHubPages) {
  csvFile = '/theimipolexg.github.io/roadsidesites.csv';
}


const map = new Map({
  target: 'map',
  layers: [
    new TileLayer({
      source: new OSM()
    })
  ],
  view: new View({
    center: fromLonLat([-87.40667, 46.54639]),
    zoom: 11
  })
});


// This stuff below adds markers.  The locations are in an external file.  I used a d3
// d3 function to parse the csv becuase I was already familiar with it from the running project.
// The parsing lines are needed to get the right data type for the number entries.

// const sitesFromFile = await csv("/roadsidesites.csv", d => ({
const sitesFromFile = await csv(csvFile, d => ({
  name: d.Name,
  desc: d.Description,
  lat: +d.Latitude,
  lon: +d.Longitude,
  page: +d.Page,
  visited: d.Visited
}));

// Create a new "feature" with each of the sites
const siteFeatures = sitesFromFile.map (v => {
  return new Feature({
    geometry: new Point(fromLonLat([v.lon, v.lat])),
    name: v.name,
    desc: v.desc,
    page: v.page,
    visited: v.visited
  });
});

// Creates a marker layer with the site "features"
const markerLayer = new VectorLayer({
  source: new VectorSource({ features: siteFeatures }),
  style: (feature) => {
    const visited = feature.get('visited'); // yes or no
    const fillColor =
      visited === "yes" ? 'rgba(0,255,0,0.6)' : 'rgba(255,0,0,0.6)';
    return new Style({
      image: new CircleStyle ({
        radius: 8,
        fill: new Fill({color: fillColor}),
        stroke: new Stroke ({ color: '#fff', width: 2 }),
      })
    });
  }
});


// Adds the layer with the site locations to the main map.
map.addLayer(markerLayer);

// Add tooltips to the markers

// Create the overlay and add it to the map
const tooltipElement = document.getElementById('tooltip');
const tooltip = new Overlay({
  element: tooltipElement,
  positioning: 'bottom-left',
  stopEvent: false,
});

map.addOverlay(tooltip);

// Add click event listener

function tooltipHTMLbuilder(feature) {
  const name = feature.get('name');
  const desc = feature.get('desc');
  const page = feature.get('page');

  return `
    <div class="tt-desc">${desc ?? ''}</div>
    <div class="tt-name">${name ?? ''}</div>
    <div class="tt-page">Page: ${page ?? ''}</div>

  `;
}

map.on('click', (evt) => {
  const feature = map.forEachFeatureAtPixel(evt.pixel, (f) => f);

  if (feature) {
    tooltip.setPosition(evt.coordinate);
//    tooltipElement.innerHTML = feature.get('name'); // from the feature's name
    tooltipElement.innerHTML = tooltipHTMLbuilder(feature);
    tooltipElement.style.display = 'block';
  } else {
    tooltipElement.style.display = 'none';
  }
});



